import sharp from "sharp";

// Marca de agua en el servidor (para re-sellar fotos ya subidas).
// La plantilla "PEKÍN GLOBAL PARTS · pekinglobalparts.com" está pre-dibujada
// como PNG (base64), así NO dependemos de fuentes del servidor (que faltan en
// el entorno serverless y hacían que el texto saliera ilegible). Se repite en
// mosaico sobre la foto, escalada al ancho de la imagen.

const TILE_B64 =
  "";
const TILE = Buffer.from(TILE_B64, "base64");

export { SELLO_VERSION } from "./sello-version";

export async function marcarAguaBuffer(input: Buffer): Promise<Buffer> {
  const img = sharp(input, { failOn: "none" }).rotate(); // respeta EXIF
  const meta = await img.metadata();
  const W = meta.width || 0;
  const H = meta.height || 0;
  if (!W || !H) throw new Error("Imagen sin dimensiones");

  const tileW = Math.max(240, Math.round(W * 0.55));
  const tile = await sharp(TILE).resize({ width: tileW }).png().toBuffer();

  return img
    .composite([{ input: tile, tile: true, blend: "over" }])
    .jpeg({ quality: 88 })
    .toBuffer();
}
